def findDaysS2SubsequenceOfS1(s1, s2, start, end):
    n, m, q = len(s1), len(s2), len(start)

    def ok(k):
        diff = [0] * (n + 1)
        for l, r in zip(start[:k], end[:k]):
            diff[l] += 1
            diff[r + 1] -= 1
        cover = j = 0
        for i in range(n):
            cover += diff[i]
            if cover == 0 and j < m and s1[i] == s2[j]:
                j += 1
        return j == m

    if not ok(0):
        return 0
    lo, hi = 0, q  # ok(lo) is always true
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if ok(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo
